            for c in ts:
                stamp(rel, r, c, color)
        for r in rs:
            for c in bs:
                stamp(rel, r, c, color)

    # Clear non-rectangular templates from the margin.
    for y in range(H):
        for x in range(sep + 1):
            if g[y][x] == 0:
                continue
            color = g[y][x]
